+add_task(function test_move_requires_more_than_edit_permission() {
+  const { canMoveCalendarEvent } = ChromeUtils.importESModule(
+    "moz-src:///comm/mail/components/calendar/content/calendar-event-calendar-options.mjs"
+  );
+  const calendarEntry = {
+    hasAccessControl: true,
+    userIsOwner: false,
+    userCanDeleteItems: true,
+  };
+  const event = {
+    recurrenceId: null,
+    aclEntry: { calendarEntry, userCanModify: true },
+    calendar: {
+      aclEntry: calendarEntry,
+      readOnly: false,
+      supportsScheduling: false,
+      getProperty: name => (name == "requiresNetwork" ? false : null),
+    },
+  };
+  Assert.ok(canMoveCalendarEvent(event));
+  calendarEntry.userCanDeleteItems = false;
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "Edit permission does not grant delete permission"
+  );
+  calendarEntry.userCanDeleteItems = true;
+  event.aclEntry.userCanModify = false;
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "Moving requires permission to modify the event"
+  );
+  event.aclEntry.userCanModify = true;
+  event.recurrenceId = {};
+  Assert.ok(!canMoveCalendarEvent(event), "An editable occurrence cannot move");
+  event.recurrenceId = null;
+  event.calendar.supportsScheduling = true;
+  event.calendar.getSchedulingSupport = () => ({ isInvitation: () => true });
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "An invitation cannot move through the editor"
+  );
+});
